// The folder tree the CRM asked for, made on the one machine that can
// actually write to OneDrive. mkdir -p semantics: already-there is success,
// because this runs on a timer and must not fail on its own past work.
const fs = require('fs');
const path = require('path');
const out = [];
for (const item of $input.all()) {
  const folder = item.json.folder;
  const subs = item.json.subfolders || [];
  const root = path.join('/data/properties', folder);
  try {
    for (const sub of subs) fs.mkdirSync(path.join(root, sub), { recursive: true });
    // The details sheet comes from the CRM as text; only this machine can
    // put it on the drive. Rewritten every pass, and its content is stable,
    // so OneDrive does not show a change unless the property changed.
    if (item.json.detailsText && item.json.detailsPath) {
      const target = path.join(root, item.json.detailsPath);
      let existing = null;
      try { existing = fs.readFileSync(target, 'utf8'); } catch (e) { existing = null; }
      if (existing !== item.json.detailsText) fs.writeFileSync(target, item.json.detailsText, 'utf8');
    }
    out.push({ json: { propertyId: item.json.propertyId, folder, ok: true } });
  } catch (err) {
    out.push({ json: { propertyId: item.json.propertyId, folder, ok: false, error: String(err.message || err).slice(0, 300) } });
  }
}
return out;
